  'Ateşin derecesinden bağımsız olarak hemen 112’yi ara: nöbet geçirme, morarma, nefes almada zorluk, bardakla bastırınca solmayan döküntü, uyandırılamama ya da aşırı uyku hâli, ense sertliği, bıngıldakta şişlik, 8 saatten uzun süre ıslak bez olmaması.': 'مهما كانت الحرارة، اتصلي فورًا برقم الطوارئ المحلي عند: التشنج، أو ازرقاق اللون، أو صعوبة التنفس، أو طفح لا يختفي بالضغط عليه بكوب، أو صعوبة الإيقاظ أو النعاس الشديد، أو تيبّس الرقبة، أو انتفاخ اليافوخ، أو عدم وجود حفاض مبلل لأكثر من 8 ساعات.',
