  'Başını daha dik tutar; ellerini birleştirip ağzına götürür. Kahkahaya yakın sesler, renkli nesnelere uzun bakma.': 'يرفع رأسه أكثر؛ ويجمع يديه ويضعهما في فمه. يكاد يضحك، ويتأمل الأشياء الملونة مدة أطول.',
  'Başını dik ve sabit tutar; nesnelere uzanır ve tutar. Kahkaha atar, yüzüstüyken kollarıyla doğrulur. Yuvarlanma denemeleri başlayabilir.': 'يرفع رأسه مستقيمًا وثابتًا؛ ويمد يده للأشياء ويمسكها. يضحك، ويستند على ذراعيه على بطنه. قد تبدأ محاولات التقلب.',
  'Başını kısa süre kaldırmayı dener; ellerini yumruk yapar. Sese irkilir veya sakinleşir. Gözüyle yakındaki yüzü kısa süre takip eder.': 'يحاول رفع رأسه لحظات؛ ويداه مقبوضتان. يجفل أو يهدأ مع الأصوات. يتابع وجهًا قريبًا بعينيه لحظات.',
