  'Bebek hareketlerinde belirgin azalma, kanama, su gelmesi, düzenli kasılmalar, şiddetli baş ağrısı veya görme bozukluğu: aynı gün başvur. Acil durumda 112.': 'انخفاض واضح في حركة الطفل، نزيف، تسرب سائل، تقلصات منتظمة، صداع شديد أو مشكلات في الرؤية: راجعي الطبيب في اليوم نفسه. وفي الطوارئ اتصلي برقم الطوارئ المحلي.',
