  'Bez, cilt ve beslenme kayıtlarını izleyin. Kontrolleri sağlık ekibinizle planlayın; ateş veya beslenme güçlüğünde yaşa uygun acil değerlendirme gereksinimini sorun.': 'تابعي سجلات الحفاض والجلد والتغذية. خططي للمتابعات مع فريقك الصحي؛ واسألي عن معايير الطوارئ حسب العمر للحمى أو صعوبات التغذية.',
