  'Doğumdan sonra işe dönüş hem duygusal hem pratik bir geçiştir; önceden planlamak kolaylaştırır.': 'العودة إلى العمل بعد الولادة انتقال عاطفي وعملي؛ والتخطيط المسبق يساعد.',
  'Doğumdan sonra nüfus kaydı ve sağlık güvencesi işlemlerinin zamanında yapılması gerekir.': 'بعد الولادة يجب إتمام إجراءات القيد المدني والتأمين الصحي في موعدها.',
