  'Doğumdan sonraki ilk günlerde topuk kanı ve işitme taraması yapılır; 3–5. günde ilk kontrol önerilir.': 'في الأيام الأولى بعد الولادة يُجرى فحص وخز الكعب وفحص السمع؛ ويُوصى بأول فحص في اليوم 3–5.',
  'Doğumdan sonraki ilk hafta içinde topuk kanı taraması ve işitme taraması yapılır.': 'يُجرى فحص وخز الكعب وفحص السمع في الأسبوع الأول بعد الولادة.',
  'Doğumdan sonraki ilk kontrolü (genellikle 3–5. gün) aksatma.': 'لا تفوّتي أول فحص بعد الولادة (عادةً في اليوم 3–5).',
