  'Düzenli ana ve ara öğün fırsatları sunun; açlık-tokluk işaretlerine saygı gösterin. Üzüm, sert kuruyemiş ve benzeri boğulma risklerini uygun şekilde hazırlayın.': 'قدّمي وجبات منتظمة ووجبات خفيفة؛ واحترمي إشارات الجوع والشبع. حضّري العنب والمكسرات الصلبة وما شابهها من مخاطر الاختناق بطريقة مناسبة.',
