  'Düzenli harcamaları ve yaklaşan ihtiyaçları yazın. Alışveriş öncesinde evdeki stokları kontrol edin.': 'دوّني النفقات المنتظمة والاحتياجات القادمة. راجعي ما لديك في المنزل قبل التسوق.',
  'Düzenli hareket, uyku ve dengeli beslenme duygudurumu destekler.': 'الحركة المنتظمة والنوم والغذاء المتوازن تدعم المزاج.',
  'Düzenli kontrol et; çatlak veya yıpranmışsa değiştir.': 'افحصيها بانتظام؛ واستبدليها إن تشققت أو بليت.',
