  'Düzenli uyku ve uyanma saatlerini not edin; çocuğun ihtiyaçlarına göre rutini uyarlayın.': 'دوّني مواعيد النوم والاستيقاظ المنتظمة؛ وكيّفي الروتين حسب احتياجات طفلك.',
  'Düzenli ve giderek sıklaşan kasılmalar, su gelmesi ve nişan gelmesi doğumun başladığını gösterebilir.': 'التقلصات المنتظمة المتقاربة، ونزول ماء الرأس، وخروج السدادة المخاطية قد تعني بدء المخاض.',
