  'Düzensiz adet, androjen fazlalığı belirtileri ve yumurtalıklarda çok sayıda küçük folikülle seyreden yaygın bir hormonal durumdur.': 'اضطراب هرموني شائع مع دورات غير منتظمة وعلامات زيادة الأندروجين وجريبات صغيرة كثيرة في المبيضين.',
  'Düzensiz adet, kronik hastalık veya önceki gebelik kayıpları varsa erkenden.': 'مبكرًا إذا كانت الدورة غير منتظمة أو هناك مرض مزمن أو حالات فقدان حمل سابقة.',
  'Düzensiz ve düzenli kasılmaları ayırt etmeye çalış.': 'حاولي التمييز بين التقلصات غير المنتظمة والمنتظمة.',
  'Düzensiz veya hiç adet görmeme, bilinen tüp veya rahim sorunu.': 'دورات غير منتظمة أو غائبة، أو مشكلة معروفة في الأنابيب أو الرحم.',
  'Düzensiz veya seyrek adet, sivilce, tüylenme ve kilo artışı görülebilir.': 'قد تظهر دورات غير منتظمة أو متباعدة وحب الشباب وزيادة الشعر وزيادة الوزن.',
  'Düzleşme 4 aydan sonra artıyorsa veya alın/kulaklarda asimetri varsa.': 'إذا ازداد التسطح بعد الشهر الرابع أو كان الجبين/الأذنان غير متناظرين.',
  'Düğme pil veya mıknatıs yutma şüphesi: hemen acil servis.': 'الاشتباه في ابتلاع بطارية زرية أو مغناطيس: توجّهي إلى الطوارئ فورًا.',
  'Düğme pilleri ve mıknatısları çocuklardan uzak tut.': 'أبعدي البطاريات الزرية والمغناطيسات عن الأطفال.',
