  'Düşme sonrası diş kırığı veya yerinden çıkma: hemen diş hekimi.': 'سن مكسورة أو مقلوعة بعد سقوط: راجعي طبيب الأسنان فورًا.',
  'Düşme ve darbe riski olan sporlar ile sırtüstü uzun süre yatmayı gerektiren hareketler önerilmez.': 'لا يُنصح بالرياضات التي فيها خطر سقوط أو صدمات، ولا بالتمارين التي تتطلب الاستلقاء على الظهر طويلًا.',
  'Düşme ve kafa travması': 'السقوط وإصابات الرأس',
  'Düşmeler, zehirlenmeler, yanıklar ve boğulma en sık ev kazalarıdır.': 'السقوط والتسمم والحروق والغرق أكثر الحوادث المنزلية شيوعًا.',
  'Düştükten sonra birkaç gün az miktarda kanlı lekelenme olabilir.': 'قد يحدث نزف خفيف بضعة أيام بعد سقوطه.',
  'Düşük ışıklı gece aydınlatması.': 'إضاءة ليلية خافتة.',
