  'Egzama kuru, kaşıntılı, kırmızı alanlarla görülür ve tekrarlayabilir.': 'تظهر الإكزيما كبقع جافة حمراء مثيرة للحكة وقد تتكرر.',
  'Egzamada akıntı, kabuklanma veya yoğun kaşıntı.': 'نزّ أو تقشر أو حكة شديدة مع الإكزيما.',
