  'Egzersiz gebelik diyabeti riskini azaltabilir, sırt ağrısını hafifletebilir.': 'قد تقلل الرياضة خطر سكري الحمل وتخفف ألم الظهر.',
  'Egzersiz sırasında kanama, su gelmesi, göğüs ağrısı, baş dönmesi, ağrılı kasılma: dur ve başvur.': 'نزيف أو تسرب سائل أو ألم في الصدر أو دوخة أو تقلصات مؤلمة أثناء الرياضة: توقفي وراجعي الطبيب.',
  'Ek enerji ihtiyacı ilk üç ayda çok azdır, sonraki aylarda günde yaklaşık 300–450 kcal artar.': 'الحاجة الإضافية للطاقة قليلة جدًا في الثلث الأول ثم ترتفع بنحو 300–450 سعرة يوميًا.',
  'Ek gıda': 'الأطعمة التكميلية',
  'Ek gıda döneminde uygun doku, hijyen ve alerjenleri göz önünde bulundurun. Boğulma riski taşıyan yiyeceklerden kaçının.': 'خلال فترة الأطعمة التكميلية، راعي القوام المناسب والنظافة ومسببات الحساسية. تجنبي الأطعمة التي قد تسبب الاختناق.',
  'Ek gıda: {0} kayıt': 'الأطعمة التكميلية: {0} سجلات',
  'Ek gıdaya 6. ay civarında, bebek hazır olduğunda başlanır; anne sütü 1 yaşına kadar ana besin olmaya devam eder.': 'تبدأ الأطعمة التكميلية قرابة الشهر السادس عندما يكون الطفل مستعدًا؛ ويبقى حليب الأم الغذاء الرئيسي حتى عمر سنة.',
  'Ek gıdaya geçiş': 'البدء بالأطعمة التكميلية',
  'Ek gıdaya geçişte kabızlık sıklaşabilir.': 'قد يزداد الإمساك مع بدء الأطعمة التكميلية.',
  'Ek gıdaya geçtiyse su ve lifli besinler (erik, armut, sebze püreleri) ver.': 'إذا بدأ طفلك بالأطعمة الصلبة، أعطيه الماء وأطعمة غنية بالألياف (الخوخ المجفف، الكمثرى، هريس الخضار).',
  'Ek gıdaya hazırlık belirtilerini ve yeni besinleri not edin. Boğulma riskini azaltan uygun kıvam ve güvenli oturma önemlidir.': 'دوّني علامات الاستعداد للأطعمة الصلبة والأطعمة الجديدة. القوام المناسب الذي يقلل خطر الاختناق والجلوس الآمن أمران مهمان.',
  'Ek gıdaya küçük miktarlarla başlayın. Demir içeren besinlere, farklı tatlara ve uygun dokulara yer verin. Anne sütü veya formül sürer.': 'ابدئي الأطعمة الصلبة بكميات صغيرة. أدرجي الأطعمة المحتوية على الحديد ومذاقات مختلفة وقوامًا مناسبًا. ويستمر حليب الأم أو الحليب الصناعي.',
  'Ek gıdaya uygun kaşık seçenekleri.': 'خيارات ملاعق مناسبة للطعام الصلب.',
