  'El yıkama, diş fırçalama ve günlük öz bakım rutinlerini birlikte uygulayın. Tuvalet alışkanlığında hazır oluşa saygı gösterin.': 'قوما معًا بغسل اليدين وتنظيف الأسنان وروتين العناية اليومية. احترمي الاستعداد فيما يخص استخدام المرحاض.',
