  'Elif’in nuru': 'نور الألف',
  'Elleri sık yıka; hasta kişilerin bebeği öpmesine izin verme.': 'اغسلي يديك كثيرًا؛ ولا تسمحي للمرضى بتقبيل الطفل.',
  'Ellerini yıka; kaynatılıp 70 °C civarına soğutulmuş su kullan.': 'اغسلي يديك؛ واستخدمي ماءً مغليًا مبرّدًا إلى نحو 70 °م.',
  'Elleriniz': 'يداك',
  'Ellerinizi yıkadıktan sonra nemlendirin. Tırnakları temiz ve kısa tutun; keskin aletlerle tırnak etini zorlamayın.': 'رطّبي يديك بعد الغسل. أبقي الأظافر نظيفة وقصيرة؛ ولا تضغطي على الجلد حول الأظافر بأدوات حادة.',
