  'Elmaları doğrayıp tarçınla karıştırarak kaba alın.': 'قطّعي التفاح واخلطيه بالقرفة وضعيه في طبق.',
  'Elmaları soyup dilimleyin; limon suyu, esmer şeker ve tarçınla karıştırıp fırın kabına yayın.': 'قشّري التفاح وقطّعيه شرائح؛ واخلطيه بعصير الليمون والسكر البني والقرفة وافرديه في طبق الفرن.',
  'Elmalı crumble': 'كرامبل التفاح',
  'Elmalı tarçınlı yulaf': 'شوفان بالتفاح والقرفة',
  'Elmalı yulaf lapası': 'عصيدة الشوفان بالتفاح',
  'Elmayı ekleyip 3 dakika daha karıştırın.': 'أضيفي التفاح وقلّبي 3 دقائق أخرى.',
  'Elmayı rendeleyin.': 'ابشري التفاحة.',
  'Elmayı yıkayıp rendeleyin.': 'اغسلي التفاحة وابشريها.',
  'Elçi kadın; ülkeyi temsil eden': 'المبعوثة؛ ممثلة البلاد',
  'Embriyo dönemi sona erer, "fetüs" dönemi başlar; hayati organlar yerini almıştır.': 'تنتهي المرحلة الجنينية الأولى وتبدأ مرحلة «الجنين»؛ والأعضاء الحيوية في مكانها.',
  'Emekleme ve tutunarak kalkma dönemi: priz kapakları, merdiven kapısı, köşe koruyucu, mobilyaları duvara sabitleme. Yürüteç kullanma.': 'مرحلة الحبو والوقوف: أغطية المقابس، بوابات الدرج، حواف الزوايا، تثبيت الأثاث بالجدار. لا تستخدمي المشاية.',
  'Emekler; tutunarak ayağa kalkmayı dener. Başparmak ve işaret parmağıyla küçük nesneleri tutmaya başlar. "baba", "mama" heceleri.': 'يحبو؛ ويحاول الوقوف. يبدأ بالتقاط الأشياء الصغيرة بالإبهام والسبابة. مقاطع مثل «بابا» و«ماما».',
  'Emicilik': 'الامتصاص',
  'Emmede isteksizlik, sürekli uyku hâli veya uyandırılamama.': 'رفض الرضاعة، أو النعاس المستمر، أو صعوبة إيقاظه.',
  'Emniyet kemeri': 'حزام الأمان',
  'Emniyet kemeri karnın altından ve göğüslerin arasından geçecek şekilde takılmalıdır.': 'يجب أن يمر حزام الأمان أسفل البطن وبين الثديين.',
  'Emzik': 'لهّاية',
  'Emzik bebeği rahatlatabilir ve uykuda kullanımı ABÖS riskini azaltabilir; doğru zamanlama önemlidir.': 'قد تهدئ اللهّاية طفلك، واستخدامها عند النوم قد يقلل خطر موت الرضع المفاجئ؛ والتوقيت مهم.',
  'Emzik kullanımı': 'استخدام اللهّاية',
  'Emzik sonrası ağızda beyaz plaklar (pamukçuk) görülürse.': 'إذا ظهرت بقع بيضاء (فطريات الفم) في الفم.',
  'Emzik uyku sırasında verilebilir; emzirme oturduktan sonra (genellikle 3–4. hafta) başlamak önerilir.': 'يمكن إعطاء اللهّاية عند النوم؛ ويفضل بعد استقرار الرضاعة الطبيعية (عادةً في الأسبوع 3–4).',
  'Emzirdiğin tarafa dokun; taraf değiştirince diğerine dokunman yeter. Bitirince kayıt beslenme günlüğüne eklenir.': 'اضغطي على الجهة التي ترضعين منها؛ وعند تبديل الجهة اضغطي على الأخرى. عند الانتهاء يُضاف السجل إلى مفكرة التغذية.',
  'Emziren annelerde östrojensiz yöntemler tercih edilir.': 'تُفضَّل الوسائل الخالية من الإستروجين للأمهات المرضعات.',
  'Emziren annenin beslenmesi': 'تغذية الأم المرضع',
  'Emzirme': 'الرضاعة الطبيعية',
  'Emzirme / besleme sorularımı not ettim': 'دوّنتُ أسئلتي عن الرضاعة / التغذية',
  'Emzirme Yastığı': 'وسادة الرضاعة',
  'Emzirme döneminde enerji ve sıvı ihtiyacı artar; özel bir diyet çoğu zaman gerekmez.': 'تزداد الحاجة إلى الطاقة والسوائل أثناء الرضاعة؛ ولا تلزم عادةً حمية خاصة.',
  'Emzirme günde yaklaşık 450–500 kcal ek enerji gerektirir.': 'تحتاج الرضاعة إلى نحو 450–500 سعرة إضافية يوميًا.',
  'Emzirme hakkında bilgi edin; uygulamadaki rehberden başlayabilirsin.': 'تعرّفي على الرضاعة الطبيعية؛ ويمكنك البدء بالدليل في التطبيق.',
  'Emzirme oturana kadar (genellikle 3–4 hafta) emzik vermemek önerilir.': 'يُنصح بعدم إعطاء اللهّاية قبل استقرار الرضاعة الطبيعية (عادةً 3–4 أسابيع).',
  'Emzirme sonrası birkaç damla sütü meme ucuna sürüp kurumaya bırak.': 'بعد الرضاعة امسحي الحلمة ببضع قطرات من الحليب واتركيها تجف.',
  'Emzirme sonrası sağmak üretimi artırabilir.': 'الشفط بعد الرضعات قد يزيد الإنتاج.',
  'Emzirme sonrası soğuk kompres ödeme iyi gelebilir.': 'كمادة باردة بعد الرضاعة قد تخفف التورم.',
  'Emzirme sütyeni': 'حمالة صدر للرضاعة',
  'Emzirme sırasında rahat pozisyon ve etkili kavrama önemlidir. Sürekli ağrı, ateş veya memede kızarıklık varsa sağlık uzmanıyla görüşün. Beslenme ve sıvı ihtiyacınızı ihmal etmeyin.': 'الوضعية المريحة والالتقام الجيد مهمان في الرضاعة. تحدثي مع مختص إذا عانيتِ من ألم مستمر أو حمى أو احمرار في الثدي. لا تهملي احتياجاتك من الطعام والسوائل.',
