  'Günlük hareket': 'الحركة اليومية',
  'Günlük hareket, iletişim ve oyun gözlemlerinizi kaydedin. Gelişim hızı çocuklar arasında değişebilir.': 'سجّلي ملاحظاتك اليومية عن الحركة والتواصل واللعب. تختلف وتيرة النمو من طفل لآخر.',
  'Günlük hareketliliğe uygun kumaş ve kalıpları seçin. Mevsim ve gün içindeki sıcaklık değişimine göre katmanlı giyinin.': 'اختاري أقمشة وقصّات تناسب نشاطك اليومي. البسي طبقات حسب الموسم وتغيرات الحرارة خلال اليوم.',
  'Günlük hızlı kayıt işlemleri': 'تسجيلات يومية سريعة',
  'Günlük işlerde küçük görevler ("ayakkabını getir"), boyama, parmak oyunları.': 'مهام صغيرة في الروتين اليومي («أحضر حذاءك»)، تلوين، ألعاب الأصابع.',
  'Günlük işleri anlatarak konuş; çocuğun söylediklerini genişleterek tekrar et.': 'صفي الأعمال اليومية بالكلام؛ وكرري ما يقوله طفلك ووسّعيه.',
  'Günlük işlevleri etkileyen yoğun sıkıntıda uzman desteği alın.': 'اطلبي دعمًا مختصًا عند ضيق شديد يؤثر في الحياة اليومية.',
