  'Günlük sesleri taklit ederek karşılıklı tekrar edin.': 'قلّدا أصوات الحياة اليومية وكرّراها بالتناوب.',
  'Günlük su taşımaya yardımcı.': 'تساعدك على حمل الماء خلال اليوم.',
  'Günlük sözcükleri, jestleri, hareketi ve öz bakım denemelerini oyun içinde gözlemleyin.': 'لاحظي من خلال اللعب الكلمات اليومية والإيماءات والحركة ومحاولات العناية بالنفس.',
  'Günlük takip': 'المتابعة اليومية',
  'Günlük veya sağlık kayıtları doğrulanamadı; doğum tarihi değiştirilmedi.': 'تعذّر التحقق من سجلات المفكرة أو الصحة؛ لم يُغيَّر تاريخ الميلاد.',
