  'Günlük yaşam sorumlulukları, anlatım, sayı ve ses oyunlarıyla okul öncesi becerileri destekleyin.': 'ادعمي مهارات ما قبل المدرسة بالمسؤوليات اليومية والقصص وألعاب الأرقام والأصوات.',
  'Günlük yaşam önerileri': 'نصائح للحياة اليومية',
