  'Günlük yaşamı uzun süre etkileyen yas ve umutsuzluk.': 'حزن ويأس يؤثران في الحياة اليومية لفترة طويلة.',
  'Günlük yemek önerilerim': 'أفكار وجباتي اليومية',
