  'Günün bir olayını hatırlayıp anlatın.': 'تذكّرا شيئًا حدث اليوم واحكياه.',
  'Günün en önemli üç işini belirleyin. Beklenmedik durumlar için takvimde esnek zaman bırakın.': 'اختاري أهم ثلاث مهام في اليوم. اتركي وقتًا مرنًا في التقويم للأمور غير المتوقعة.',
  'Günün kayıtları': 'سجلات اليوم',
  'Günün sevilen anlarını kısa cümlelerle paylaşın.': 'تشاركا أجمل لحظات اليوم بجمل قصيرة.',
  'Günün sonunda nasıl hissettiğinizi birkaç kelimeyle yazın. Duygunuzu değiştirmeye zorlamadan fark etmeye çalışın.': 'في نهاية اليوم اكتبي شعورك ببضع كلمات. حاولي ملاحظة الشعور دون إجبار نفسك على تغييره.',
