  'Güveci folyoyla kapatıp fırında 20 dakika, patatesler yarı yumuşayana kadar pişirin.': 'غطّي الطاجن بورق الألومنيوم واخبزيه 20 دقيقة حتى تلين البطاطا إلى النصف.',
  'Güvecin içinde, yanında taze ekmekle sıcak servis edin.': 'قدّميه ساخنًا في الطاجن مع خبز طازج.',
