  'Güvenilir bir bakım düzeni hem çocuğun hem ailenin huzuru için önemlidir.': 'الرعاية الموثوقة مهمة لطمأنينة الطفل والأسرة.',
  'Güvenilir ve yüce': 'الأمين الرفيع',
  'Güvenilir, emin; Hz. Muhammed’in annesi': 'الأمينة؛ والدة النبي محمد',
