  'Güvenli uyku ortamı': 'بيئة النوم الآمنة',
  'Güvenli uyku rehberlerine uyun; yumuşak nesnelerden kaçının.': 'اتبعي إرشادات النوم الآمن؛ وتجنبي الأشياء الطرية.',
  'Güvenli uyku, bal, şeker ve ekran gibi konularda öneriler zaman içinde değişmiştir.': 'تغيرت التوصيات بشأن النوم الآمن والعسل والسكر والشاشات مع الوقت.',
  'Güvenli veri taşıma doğrulanamadı: {0}': 'تعذّر التحقق من نقل البيانات الآمن: {0}',
  'Güvenli yedek kayıt türü geçersiz.': 'نوع سجل النسخة الآمنة غير صالح.',
  'Güvenlik': 'السلامة',
  'Güvenlik kaygısı içeren ilişkilerde profesyonel destek alın.': 'اطلبي دعمًا مختصًا في العلاقات التي تنطوي على مخاوف تتعلق بالسلامة.',
  'Güvenlik standardı gerektirmeyen ürünlerde ikinci el seçenekleri değerlendir (oto koltuğu hariç).': 'فكّري في المستعمل للمنتجات التي لا تتطلب معايير سلامة (ما عدا مقاعد السيارة).',
  'Güvenlik ve İlk Yardım': 'السلامة والإسعافات الأولية',
  'Güvenlik önlemleri gözetimin yerini almaz.': 'تدابير السلامة لا تغني عن الإشراف.',
  'Güvenlik: 12 aydan küçük bebeklere bal vermeyin. Bütün kuruyemiş, bütün üzüm ve sert/yuvarlak parçalar boğulma riski taşır. Yeni alerjenler ve özel sağlık durumları için sağlık uzmanına danışın. Tarifler kişisel tıbbi tavsiye değildir.': 'السلامة: لا تعطي العسل للرضع دون 12 شهرًا. المكسرات الكاملة والعنب الكامل والقطع الصلبة/المستديرة تسبب خطر الاختناق. اسألي مختصًا صحيًا عن مسببات الحساسية الجديدة والحالات الصحية الخاصة. الوصفات ليست نصيحة طبية شخصية.',
