  'Yedekler AES-256-GCM ile parola kullanılarak şifrelenir. Parolanızı unutursanız yedeği açamazsınız. Panoya kopyalanan yedek metnini yine de güvenle saklayın. ÖNEMLİ: Bu işlem cihazdaki canlı kayıtları şifrelemez; bulut yedekleme değildir.': 'تُشفَّر النسخ الاحتياطية بـ AES-256-GCM باستخدام كلمة مرور. إذا نسيتِ كلمة المرور فلن تتمكني من فتح النسخة. ومع ذلك احفظي نص النسخة المنسوخ إلى الحافظة بأمان. مهم: هذا لا يشفّر السجلات الحالية على الجهاز؛ وليس نسخًا سحابيًا.',
