  'Yenidoğan yüzleri 20–30 cm mesafeden en iyi görür, annesinin sesini ve kokusunu tanır. Emme, yakalama ve irkilme refleksleri vardır.': 'يرى حديثو الولادة الوجوه بأفضل وضوح على بعد 20–30 سم، ويتعرفون على صوت الأم ورائحتها. ولديهم منعكسات المص والقبض والإجفال.',
