  'Yenidoğanlar ilk günlerde doğum kilosunun yaklaşık %7–10\'unu kaybedebilir; çoğu 10–14 gün içinde geri kazanır.': 'قد يفقد حديثو الولادة نحو 7–10% من وزن الولادة في الأيام الأولى؛ ويستعيده معظمهم خلال 10–14 يومًا.',
  'Yenidoğanların çoğunda ilk günlerde ciltte sarılık görülür; çoğu zararsızdır ama takip gerektirir.': 'يصاب معظم حديثي الولادة باصفرار الجلد في الأيام الأولى؛ وهو غالبًا غير ضار لكنه يحتاج إلى متابعة.',
