  'Yerde güvenli bir alanda, oturma ve uzanma becerisine göre yetişkin yardımıyla oynayın.': 'العبا على الأرض في مكان آمن، بمساعدة شخص بالغ حسب مهاراته في الجلوس والاستلقاء.',
