  'Yüklenen referanslar yalnızca bu ekran açıkken tutulur. 0–24 ay aylık WHO persentilleri bilgi amaçlıdır; tıbbi değerlendirme değildir.': 'تبقى المراجع المحمّلة فقط ما دامت هذه الشاشة مفتوحة. مئينات منظمة الصحة العالمية الشهرية لـ 0–24 شهرًا للمعلومات؛ وليست تقييمًا طبيًا.',
  'Yüksek ateş, aşırı halsizlik veya uyandırmakta güçlük.': 'حمى مرتفعة، أو ضعف شديد، أو صعوبة في الإيقاظ.',
  'Yüksek ateş, nefes darlığı, bayılma, nöbet: 112.': 'حمى مرتفعة، ضيق تنفس، إغماء، تشنج: اتصلي برقم الطوارئ المحلي.',
  'Yüksek sarılık değerleri tedavi edilmezse zarar verebilir; bu nedenle kontrol önemlidir.': 'المستويات المرتفعة جدًا من اليرقان قد تضر إن لم تُعالج، لذا فالمتابعة مهمة.',
  'Yüksek yüzeylerde yalnız bırakmayın. Küçük parçaları, kabloları, ilaçları ve sıcak içecekleri erişimden uzak tutun; uygun oto koltuğu kullanın.': 'لا تتركيه وحده على الأسطح المرتفعة. أبعدي القطع الصغيرة والأسلاك والأدوية والمشروبات الساخنة؛ واستخدمي مقعد سيارة مناسبًا.',
  'Yüksek ısı ve tek kat dizmek karnabaharın haşlanmak yerine kavrulmasını sağlar.': 'الحرارة العالية والطبقة الواحدة تجعل القرنبيط يُشوى بدل أن يُسلق.',
