  'Yürüme, ilk kelimeler ve bağımsızlık isteği bu dönemin öne çıkan özellikleridir.': 'المشي والكلمات الأولى والرغبة في الاستقلال أبرز ما يميز هذه المرحلة.',
  'Yürüteç kullanma: düşme ve yaralanma riskini artırır.': 'لا تستخدمي المشاية: فهي تزيد خطر السقوط والإصابات.',
  'Yürüyüş, yüzme, sabit bisiklet ve gebe yogası güvenli seçeneklerdir.': 'المشي والسباحة والدراجة الثابتة ويوغا الحوامل خيارات آمنة.',
