  'Yüz ifadeleri başlayabilir; vücudu ince tüylerle (lanugo) kaplanmaya başlar.': 'قد تبدأ تعابير الوجه؛ ويبدأ الجسم بالتغطي بزغب ناعم (الزغب الجنيني).',
  'Yüz ifadelerini keşfet': 'استكشاف تعابير الوجه',
  'Yüz temizliği, nemlendirme ve güneşten korunmayı üç kısa adıma bölün. Yeni ürünleri tek tek ekleyerek cildinizin tepkisini gözlemleyin.': 'قسّمي تنظيف الوجه والترطيب والحماية من الشمس إلى ثلاث خطوات قصيرة. أضيفي المنتجات الجديدة واحدًا تلو الآخر وراقبي تفاعل بشرتك.',
  'Yüz ve ellerde ani şişlik, nefes darlığı: hemen başvur.': 'تورم مفاجئ في الوجه واليدين، ضيق تنفس: اطلبي المساعدة فورًا.',
  'Yüz-dil şişmesi, solunum güçlüğü veya baygınlık gibi bulgular acil değerlendirme gerektirir.': 'علامات مثل تورم الوجه أو اللسان أو صعوبة التنفس أو الإغماء تحتاج إلى تقييم طارئ.',
