  'İçerik': 'المحتويات',
  'İçerik etiketini inceleyin.': 'راجعي ملصق المكونات.',
  'İçerikler bilgilendirme amaçlıdır, tıbbi tavsiye değildir. Döngü tahminleri yaklaşıktır ve doğum kontrolü için kullanılmamalıdır. Acil durumda 112\'yi ara.': 'المحتوى للمعلومات وليس نصيحة طبية. توقعات الدورة تقريبية ولا يجوز استخدامها لمنع الحمل. في الطوارئ اتصلي برقم الطوارئ المحلي.',
